-- ITH-111: "Reporting manager approves first" as a workflow setting, plain-English explanations, workflows for every request category.
ALTER TABLE itsm_workflows ADD COLUMN IF NOT EXISTS manager_approval boolean NOT NULL DEFAULT false;
ALTER TABLE itsm_workflows ADD COLUMN IF NOT EXISTS manager_level int NOT NULL DEFAULT 1;
INSERT INTO itsm_workflows (ticket_type, name, description, match, rank, manager_approval, is_active, created_by, updated_by)
SELECT 'request', 'Email / user ID creation (manager approval)', 'New email ID, new user ID, shared mailbox, distribution list or mailbox size: the reporting manager approves first, then IT sets it up within a day (team reminded after 24 h) and the requester is told.', '{"category": ["Account Setup", "Email Setup"]}'::jsonb, 5, true, false, 'System (preconfigured)', 'System (preconfigured)'
WHERE NOT EXISTS (SELECT 1 FROM itsm_workflows WHERE ticket_type = 'request' AND lower(name) = lower('Email / user ID creation (manager approval)'));
INSERT INTO itsm_workflow_versions (workflow_id, version, status, definition, notes, created_by, updated_by, published_by, published_at)
SELECT w.id, 1, 'Published', '{"nodes": [{"id": "s", "type": "start", "label": "Raised", "x": 40, "y": 240, "config": {}}, {"id": "w", "type": "stage", "label": "IT creating", "x": 240, "y": 240, "config": {"status": "In Progress", "timeoutHours": 24}}, {"id": "rem", "type": "notify", "label": "Remind team", "x": 240, "y": 60, "config": {"to": ["team"], "title": "{no} pending", "message": "{no}: {title} is waiting more than a day."}}, {"id": "h", "type": "stage", "label": "On hold", "x": 460, "y": 420, "config": {"status": "On Hold"}}, {"id": "done", "type": "stage", "label": "Completed", "x": 460, "y": 240, "config": {"status": "Completed"}}, {"id": "nd", "type": "notify", "label": "Tell requester", "x": 680, "y": 240, "config": {"to": ["requester"], "title": "{no} done", "message": "{no}: {title} is ready."}}, {"id": "end", "type": "end", "label": "Done", "x": 900, "y": 240, "config": {}}], "edges": [{"id": "s-w-next", "from": "s", "to": "w", "label": "", "outcome": "next"}, {"id": "w-rem-timeout", "from": "w", "to": "rem", "label": "", "outcome": "timeout"}, {"id": "rem-w-next", "from": "rem", "to": "w", "label": "", "outcome": "next"}, {"id": "w-h-next", "from": "w", "to": "h", "label": "Put on hold", "outcome": "next"}, {"id": "h-w-next", "from": "h", "to": "w", "label": "Resume", "outcome": "next"}, {"id": "w-done-next", "from": "w", "to": "done", "label": "Complete", "outcome": "next"}, {"id": "done-nd-next", "from": "done", "to": "nd", "label": "Finish", "outcome": "next"}, {"id": "nd-end-next", "from": "nd", "to": "end", "label": "", "outcome": "next"}]}'::jsonb, 'Preconfigured', 'System (preconfigured)', 'System (preconfigured)', 'System (preconfigured)', now()
FROM itsm_workflows w WHERE w.ticket_type = 'request' AND lower(w.name) = lower('Email / user ID creation (manager approval)') AND NOT EXISTS (SELECT 1 FROM itsm_workflow_versions v WHERE v.workflow_id = w.id);
INSERT INTO itsm_workflows (ticket_type, name, description, match, rank, manager_approval, is_active, created_by, updated_by)
SELECT 'request', 'IT hardware & accessories (manager approval)', 'Mouse, keyboard, headset, monitor, docking station, laptop / desktop: the reporting manager approves first; laptops, desktops, monitors and docking stations also need IT Asset Admin approval; IT issues from stock or procures (team reminded after 3 days) and the requester is told when it is ready for handover.', '{"category": ["Hardware Request"]}'::jsonb, 5, true, false, 'System (preconfigured)', 'System (preconfigured)'
WHERE NOT EXISTS (SELECT 1 FROM itsm_workflows WHERE ticket_type = 'request' AND lower(name) = lower('IT hardware & accessories (manager approval)'));
