": "next"}, {"id": "c-aa-yes", "from": "c", "to": "aa", "label": "", "outcome": "yes"}, {"id": "c-nok-no", "from": "c", "to": "nok", "label": "", "outcome": "no"}, {"id": "aa-nok-approved", "from": "aa", "to": "nok", "label": "", "outcome": "approved"}, {"id": "aa-nrej-rejected", "from": "aa", "to": "nrej", "label": "", "outcome": "rejected"}, {"id": "nrej-rej-next", "from": "nrej", "to": "rej", "label": "", "outcome": "next"}, {"id": "nok-w-next", "from": "nok", "to": "w", "label": "", "outcome": "next"}, {"id": "w-rem-timeout", "from": "w", "to": "rem", "label": "", "outcome": "timeout"}, {"id": "rem-w-next", "from": "rem", "to": "w", "label": "", "outcome": "next"}, {"id": "w-h-next", "from": "w", "to": "h", "label": "Awaiting delivery", "outcome": "next"}, {"id": "h-w-next", "from": "h", "to": "w", "label": "Received", "outcome": "next"}, {"id": "w-done-next", "from": "w", "to": "done", "label": "Issue to employee", "outcome": "next"}, {"id": "done-nd-next", "from": "done", "to": "nd", "label": "Finish", "outcome": "next"}, {"id": "nd-end-next", "from": "nd", "to": "end", "label": "", "outcome": "next"}]}'::jsonb, 'Preconfigured', 'System (preconfigured)', 'System (preconfigured)', 'System (preconfigured)', now()
FROM itsm_workflows w WHERE w.ticket_type = 'request' AND lower(w.name) = lower('IT hardware & accessories (manager approval)') AND NOT EXISTS (SELECT 1 FROM itsm_workflow_versions v WHERE v.workflow_id = w.id);
