UPDATE itsm_workflow_versions v SET definition = '{"nodes": [{"id": "s", "type": "start", "label": "Raised", "x": 40, "y": 240, "config": {}}, {"id": "c", "type": "condition", "label": "Admin rights?", "x": 240, "y": 240, "config": {"field": "subcategory", "op": "contains", "value": "Admin rights"}}, {"id": "ia", "type": "approval", "label": "ITSM Admin approval", "x": 460, "y": 100, "config": {"approverType": "itsm_admins", "title": "Admin rights for {no}"}}, {"id": "nrej", "type": "notify", "label": "Tell requester: rejected", "x": 680, "y": 440, "config": {"to": ["requester"], "title": "{no} not approved", "message": "{no}: {title} was not approved."}}, {"id": "rej", "type": "end", "label": "Rejected", "x": 900, "y": 440, "config": {"status": "Rejected"}}, {"id": "w", "type": "stage", "label": "Granting access", "x": 680, "y": 240, "config": {"status": "In Progress"}}, {"id": "h", "type": "stage", "label": "On hold", "x": 900, "y": 420, "config": {"status": "On Hold"}}, {"id": "done", "type": "stage", "label": "Completed", "x": 900, "y": 240, "config": {"status": "Completed"}}, {"id": "nd", "type": "notify", "label": "Tell requester", "x": 1120, "y": 240, "config": {"to": ["requester"], "title": "{no} done", "message": "{no}: {title} - access is granted."}}, {"id": "end", "type": "end", "label": "Done", "x": 1340, "y": 240, "config": {}}], "edges": [{"id": "s-c-next", "from": "s", "to": "c", "label": "", "outcome": "next"}, {"id": "c-ia-yes", "from": "c", "to": "ia", "label": "", "outcome": "yes"}, {"id": "c-w-no", "from": "c", "to": "w", "label": "", "outcome": "no"}, {"id": "ia-w-approved", "from": "ia", "to": "w", "label": "", "outcome": "approved"}, {"id": "ia-nrej-rejected", "from": "ia", "to": "nrej", "label": "", "outcome": "rejected"}, {"id": "nrej-rej-next", "from": "nrej", "to": "rej", "label": "", "outcome": "next"}, {"id": "w-h-next", "from": "w", "to": "h", "label": "Put on hold", "outcome": "next"}, {"id": "h-w-next", "from": "h", "to": "w", "label": "Resume", "outcome": "next"}, {"id": "w-done-next", "from": "w", "to": "done", "label": "Complete", "outcome": "next"}, {"id": "done-nd-next", "from": "done", "to": "nd", "label": "Finish", "outcome": "next"}, {"id": "nd-end-next", "from": "nd", "to": "end", "label": "", "outcome": "next"}]}'::jsonb, notes = 'Preconfigured (manager approval moved to the workflow setting)'
FROM itsm_workflows w WHERE v.workflow_id = w.id AND w.ticket_type = 'request' AND w.name = 'Access request (manager approval)' AND w.created_by = 'System (preconfigured)' AND v.version = 1
  AND v.definition::text LIKE '%reporting_manager%' AND NOT EXISTS (SELECT 1 FROM itsm_ticket_workflows i WHERE i.version_id = v.id);
UPDATE itsm_workflows w SET manager_approval = true, description = 'Application access, shared folder, VPN or admin rights: the reporting manager approves first; admin rights also need ITSM Admin approval; then IT grants it and the requester is told.' WHERE w.ticket_type = 'request' AND w.name = 'Access request (manager approval)' AND w.created_by = 'System (preconfigured)' AND NOT w.manager_approval
  AND EXISTS (SELECT 1 FROM itsm_workflow_versions v WHERE v.workflow_id = w.id AND v.version = 1 AND v.definition::text NOT LIKE '%reporting_manager%');
UPDATE itsm_workflow_versions v SET definition = '{"nodes": [{"id": "s", "type": "start", "label": "Raised", "x": 40, "y": 240, "config": {}}, {"id": "w", "type": "stage", "label": "IT preparing kit & accounts", "x": 240, "y": 240, "config": {"status": "In Progress"}}, {"id": "h", "type": "stage", "label": "On hold", "x": 460, "y": 420, "config": {"status": "On Hold"}}, {"id": "done", "type": "stage", "label": "Ready", "x": 460, "y": 240, "config": {"status": "Completed"}}, {"id": "nd", "type": "notify", "label": "Tell requester", "x": 680, "y": 240, "config": {"to": ["requester"], "title": "{no} done", "message": "{no}: {title} - IT kit and accounts are ready."}}, {"id": "end", "type": "end", "label": "Done", "x": 900, "y": 240, "config": {}}], "edges": [{"id": "s-w-next", "from": "s", "to": "w", "label": "", "outcome": "next"}, {"id": "w-h-next", "from": "w", "to": "h", "label": "Put on hold", "outcome": "next"}, {"id": "h-w-next", "from": "h", "to": "w", "label": "Resume", "outcome": "next"}, {"id": "w-done-next", "from": "w", "to": "done", "label": "Complete", "outcome": "next"}, {"id": "done-nd-next", "from": "done", "to": "nd", "label": "Finish", "outcome": "next"}, {"id": "nd-end-next", "from": "nd", "to": "end", "label": "", "outcome": "next"}]}'::jsonb, notes = 'Preconfigured (manager approval moved to the workflow setting)'
FROM itsm_workflows w WHERE v.workflow_id = w.id AND w.ticket_type = 'request' AND w.name = 'New joiner onboarding (manager approval)' AND w.created_by = 'System (preconfigured)' AND v.version = 1
  AND v.definition::text LIKE '%reporting_manager%' AND NOT EXISTS (SELECT 1 FROM itsm_ticket_workflows i WHERE i.version_id = v.id);
UPDATE itsm_workflows w SET manager_approval = true, description = 'New joiner: the joiner''s reporting manager confirms first, then IT prepares accounts, email and the laptop before the joining date and the requester is told.' WHERE w.ticket_type = 'request' AND w.name = 'New joiner onboarding (manager approval)' AND w.created_by = 'System (preconfigured)' AND NOT w.manager_approval
  AND EXISTS (SELECT 1 FROM itsm_workflow_versions v WHERE v.workflow_id = w.id AND v.version = 1 AND v.definition::text NOT LIKE '%reporting_manager%');
ALTER TABLE itsm_workflow_versions ENABLE TRIGGER itsm_workflow_versions_guard;
INSERT INTO audit_logs (entity_type, entity_id, action, performed_by, summary)
SELECT 'itsm_workflow', w.id, 'create', 'System (preconfigured)', 'Preconfigured workflow “' || w.name || '” added (published v1, disabled)'
FROM itsm_workflows w WHERE w.created_by = 'System (preconfigured)' AND NOT EXISTS (SELECT 1 FROM audit_logs a WHERE a.entity_type = 'itsm_workflow' AND a.entity_id = w.id AND a.action = 'create');
